// Normal Function
function add(a, b, c) {
  return a + b + c;
}

// Curried Version
function curriedAdd(a) {
  return function(b) {
    return function(c) {
      return a + b + c;
    }
  }
}

// Using Arrow Functions for much cleaner syntax
const arrowCurryAdd = a => b => c => a + b + c;

console.log(curriedAdd(1)(2)(3)); // 6
console.log(arrowCurryAdd(10)(20)(30)); // 60

// Practical Partial Application Example
const applyDiscount = discount => price => price - (price * discount);

const tenPercentOff = applyDiscount(0.10);
const twentyPercentOff = applyDiscount(0.20);

console.log(tenPercentOff(100)); // 90
console.log(twentyPercentOff(100)); // 80
